// Item value table (keep/drop scoring)
//
// MIGRATED DATA - generated by tools/migrate/extract-aiplayers.mjs from the
// AI Players Add-On (Gamemode One) that previously lived in this repo:
//   Data/InventoryData.js
// The original generator for the upstream pack was its own build; this is a
// straight lift of the tables plus the notes below. See docs/MIGRATION.md.
//
// Used by inventory triage: what to keep when the bag is full and what is junk.
// Values are relative weights, not prices.
//
// Engine-free by construction: data only, no @minecraft imports.

export const ITEM_VALUES = {
        "minecraft:torch": 8,
        "minecraft:crafting_table": 8,
        "minecraft:furnace": 8,
        "minecraft:coal": 6,
        "minecraft:redstone": 5,
        "minecraft:lapis_lazuli": 5,
        "minecraft:stone": 4,
        "minecraft:cobblestone": 4,
        "minecraft:deepslate": 4,
        "minecraft:stick": 3,
        "minecraft:dirt": 2
    };

export function itemValue(typeId) {
    return ITEM_VALUES[typeId] ?? 0;
}
